//! Codex driver: runs the user's installed, signed-in `codex` CLI as `codex app-server` and speaks
//! its JSON-RPC protocol over stdio (newline-delimited JSON, `jsonrpc` omitted).
//!
//! # Sources
//!
//! - Protocol shapes: the schema generated by `codex app-server generate-json-schema` from
//!   codex-cli 0.163.0 (`v2/ThreadStartParams.json`, `v2/TurnStartParams.json`,
//!   `v2/ModelListResponse.json`, `ServerRequest.json`, `CommandExecutionRequestApprovalResponse.json`,
//!   `FileChangeRequestApprovalResponse.json`, `McpServerElicitationRequestResponse.json`,
//!   `v2/ItemCompletedNotification.json`). The schema is authoritative over the prose docs.
//! - Config overrides: `codex --help` ("`-c, --config <key=value>` … The `value` portion is parsed as
//!   TOML"), and the config reference <https://learn.chatgpt.com/docs/config-file/config-reference>
//!   for `mcp_servers.<id>.url` and `mcp_servers.<id>.bearer_token_env_var`.
//! - Live check (2026-10-16, codex-cli 0.163.0, signed in): `initialize`, `thread/start` with the
//!   overrides below, and `model/list` all returned results. No turn was started.
//!
//! # Launch
//!
//! `codex -c mcp_servers.renderly.url="http://127.0.0.1:<port>/mcp" -c
//! mcp_servers.renderly.bearer_token_env_var="RENDERLY_AGENT_TOKEN" -c project_doc_max_bytes=0
//! app-server`, with `RENDERLY_AGENT_TOKEN=<session token>` in the child's environment. The token
//! is never in argv. The user's `~/.codex/config.toml` is not edited and `CODEX_HOME` is not set.
//!
//! - `project_doc_max_bytes=0` asks Codex to read no project `AGENTS.md`. The session runs in a
//!   scratch folder, so there is none to read anyway. The docs describe the key only as a size cap;
//!   that 0 disables the file is NOT verified.
//! - Renderly's brief is sent as `thread/start.baseInstructions`, which the schema documents as the
//!   replacement for the built-in instructions. (`developerInstructions` would add to them.)
//! - `thread/start`: `cwd` (scratch folder), `sandbox` (`read-only` by default; `workspace-write`
//!   when "Let the agent use its own tools" is on), `approvalPolicy` `on-request`, and `model`
//!   when the user chose one.
//! - `turn/start`: `threadId`, `input: [{type:"text", text}]`, and `effort` when chosen.
//! - `turn/interrupt`: `threadId`, `turnId`. The turn ends with status `interrupted`.
//!
//! # Approvals (answered by the broker)
//!
//! - `item/commandExecution/requestApproval` and `item/fileChange/requestApproval` (params per the
//!   `*Params.json` schemas): with tools off, declined with no prompt; with tools on, asked. The
//!   response is `{"decision":"accept"|"decline"}`.
//! - `mcpServer/elicitation/request` for the `renderly` server: accepted (Renderly's own tools are
//!   pre-allowed, as in Claude Code). Other servers are declined. The response is
//!   `{"action":"accept"|"decline"}`. Whether Codex sends this for Renderly tool calls is NOT
//!   verified; the verification step is in docs/qa-checklist.md.
//! - Any other server request gets a JSON-RPC error (dynamic tools are not registered, so
//!   `item/tool/call` never arrives).
//!
//! # Model list
//!
//! `model/list` (params `{includeHidden: false}`) returns `{data: [Model], nextCursor}`; see
//! `models::parse_codex_models`. `fetch_codex_models` runs the handshake and that one request.

use super::driver::{
    json_line, AgentDriver, AgentId, AgentSession, LaunchOptions, McpEndpointInfo, SessionConfig,
};
use super::events::{summarize, AgentEnvelope, AgentEvent, EventSink};
use super::models::{parse_codex_models, AgentModels, ModelStatus};
use super::process::{self, StderrTail};
use serde_json::{json, Value};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::mpsc::{channel, Sender};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const READY_TIMEOUT: Duration = Duration::from_secs(30);
const INTERRUPT_WAIT: Duration = Duration::from_secs(2);
const MODEL_LIST_TIMEOUT: Duration = Duration::from_secs(30);

/// The environment variable that carries the session's bearer token to Codex.
pub const TOKEN_ENV: &str = "RENDERLY_AGENT_TOKEN";

pub struct CodexDriver;

impl AgentDriver for CodexDriver {
    fn agent(&self) -> AgentId {
        AgentId::Codex
    }

    fn start(&self, cfg: &SessionConfig) -> Result<Box<dyn AgentSession>, String> {
        let program = match &cfg.program {
            Some(p) => p.clone(),
            None => process::resolve_program(AgentId::Codex.program_name())
                .ok_or("Codex (codex) is not installed or not on PATH")?,
        };
        let endpoint = cfg
            .mcp_endpoint
            .clone()
            .ok_or("the Renderly tool server is not running for this session")?;
        cfg.options.clone().validated()?;
        let mut session = CodexSession {
            cfg: cfg.clone(),
            program,
            endpoint,
            child: None,
            stdin: Arc::new(Mutex::new(None)),
            thread_id: Arc::new(Mutex::new(None)),
            turn_id: Arc::new(Mutex::new(None)),
            next_id: AtomicU64::new(10),
            turn_active: Arc::new(AtomicBool::new(false)),
            alive: Arc::new(AtomicBool::new(false)),
        };
        session.spawn()?;
        Ok(Box::new(session))
    }
}

/// Argv for `codex app-server`: the Renderly server as config overrides, then the subcommand.
/// The token is not here; it is passed in the environment as [`TOKEN_ENV`].
pub fn codex_args(endpoint: &McpEndpointInfo) -> Vec<String> {
    vec![
        "-c".into(),
        format!("mcp_servers.renderly.url=\"{}\"", endpoint.url),
        "-c".into(),
        format!("mcp_servers.renderly.bearer_token_env_var=\"{TOKEN_ENV}\""),
        // Renderly's own tools never prompt (edits are undoable and grouped per turn), same as
        // the Claude driver. Without this Codex refused every Renderly tool call in a live run
        // with codex-cli 0.163.0 ("the Renderly MCP tool requires approval").
        "-c".into(),
        "mcp_servers.renderly.default_tools_approval_mode=\"approve\"".into(),
        "-c".into(),
        "project_doc_max_bytes=0".into(),
        "app-server".into(),
    ]
}

/// The `thread/start` params for a session. Pure, so the override set is unit-tested.
pub fn thread_start_params(cwd: &Path, brief: &str, options: &LaunchOptions) -> Value {
    let (sandbox, _) = sandbox_for(options);
    let mut params = json!({
        "cwd": cwd.to_string_lossy(),
        "approvalPolicy": "on-request",
        "sandbox": sandbox,
        "baseInstructions": brief,
    });
    if let Some(model) = &options.model {
        params["model"] = json!(model);
    }
    params
}

/// The sandbox for a session, and whether the agent's own tools may run. With the switch off the
/// agent cannot write, and its shell and file approvals are declined without a prompt.
pub fn sandbox_for(options: &LaunchOptions) -> (&'static str, bool) {
    if options.native_tools {
        ("workspace-write", true)
    } else {
        ("read-only", false)
    }
}

/// The `turn/start` params for one user turn.
pub fn turn_start_params(thread: &str, text: &str, options: &LaunchOptions) -> Value {
    let mut params = json!({
        "threadId": thread,
        "input": [{ "type": "text", "text": text }],
    });
    if let Some(effort) = &options.effort {
        params["effort"] = json!(effort);
    }
    params
}

/// What one line from the server means to the driver.
#[derive(Debug, PartialEq)]
pub enum Incoming {
    /// Answer to one of our requests.
    Response {
        id: u64,
        result: Value,
        error: Option<Value>,
    },
    /// The server asks us something (approvals). `id` is echoed back.
    Request {
        id: Value,
        method: String,
        params: Value,
    },
    Notification {
        method: String,
        params: Value,
    },
    Unknown,
}

pub fn classify(line: &str) -> Incoming {
    let Ok(v) = serde_json::from_str::<Value>(line) else {
        return Incoming::Unknown;
    };
    let method = v.get("method").and_then(Value::as_str).map(str::to_string);
    let params = v.get("params").cloned().unwrap_or(Value::Null);
    match (method, v.get("id")) {
        (Some(method), Some(id)) => Incoming::Request {
            id: id.clone(),
            method,
            params,
        },
        (Some(method), None) => Incoming::Notification { method, params },
        (None, Some(id)) => match id.as_u64() {
            Some(id) => Incoming::Response {
                id,
                result: v.get("result").cloned().unwrap_or(Value::Null),
                error: v.get("error").cloned(),
            },
            None => Incoming::Unknown,
        },
        (None, None) => Incoming::Unknown,
    }
}

/// Map a server notification to the normalised events. Unknown methods produce nothing.
pub fn notification_events(method: &str, params: &Value) -> Vec<AgentEvent> {
    match method {
        "item/agentMessage/delta" => {
            let text = params
                .get("delta")
                .or_else(|| params.get("text"))
                .and_then(Value::as_str)
                .unwrap_or("");
            if text.is_empty() {
                Vec::new()
            } else {
                vec![AgentEvent::TextDelta {
                    text: text.to_string(),
                }]
            }
        }
        "item/started" => {
            let Some(item) = params.get("item") else {
                return Vec::new();
            };
            match tool_card(item) {
                Some((id, name, input)) => vec![AgentEvent::ToolStarted { id, name, input }],
                None => Vec::new(),
            }
        }
        "item/completed" => {
            let Some(item) = params.get("item") else {
                return Vec::new();
            };
            match tool_card(item) {
                Some((id, _, _)) => {
                    let status = item.get("status").and_then(Value::as_str).unwrap_or("");
                    let output = item
                        .get("aggregatedOutput")
                        .and_then(Value::as_str)
                        .map(str::to_string)
                        .or_else(|| mcp_result_text(item.get("result")))
                        .unwrap_or_else(|| status.to_string());
                    vec![AgentEvent::ToolFinished {
                        id,
                        output_summary: summarize(&output, 400),
                        is_error: status == "failed" || status == "declined",
                    }]
                }
                None => Vec::new(),
            }
        }
        "turn/completed" => {
            let turn = params.get("turn");
            let status = turn
                .and_then(|t| t.get("status"))
                .and_then(Value::as_str)
                .unwrap_or("completed")
                .to_string();
            let mut events = Vec::new();
            if status == "failed" {
                let message = turn
                    .and_then(|t| t.get("error"))
                    .and_then(|e| e.get("message"))
                    .and_then(Value::as_str)
                    .unwrap_or("Codex turn failed")
                    .to_string();
                events.push(AgentEvent::Error { message });
            }
            events.push(AgentEvent::TurnFinished {
                stop_reason: status,
            });
            events
        }
        "error" => {
            let message = params
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("Codex reported an error")
                .to_string();
            vec![AgentEvent::Error { message }]
        }
        _ => Vec::new(),
    }
}

/// The text of an MCP tool result (`result.content[].text`), joined.
fn mcp_result_text(result: Option<&Value>) -> Option<String> {
    let items = result?.get("content")?.as_array()?;
    let text: Vec<&str> = items
        .iter()
        .filter_map(|i| i.get("text").and_then(Value::as_str))
        .collect();
    (!text.is_empty()).then(|| text.join("\n"))
}

/// Tool-call card for the item kinds Renderly shows. Messages, reasoning and user items are not
/// tool calls and return `None`. A call to the `renderly` MCP server is named as Claude Code names
/// it (`mcp__renderly__<tool>`), so the panel shows the same action lines for both agents.
fn tool_card(item: &Value) -> Option<(String, String, Value)> {
    let id = item.get("id").and_then(Value::as_str)?.to_string();
    match item.get("type").and_then(Value::as_str)? {
        "commandExecution" => Some((
            id,
            "shell".into(),
            json!({ "command": item.get("command").cloned().unwrap_or(Value::Null) }),
        )),
        "mcpToolCall" => {
            let server = item.get("server").and_then(Value::as_str).unwrap_or("mcp");
            let tool = item.get("tool").and_then(Value::as_str).unwrap_or("tool");
            let name = if server == "renderly" {
                format!("mcp__renderly__{tool}")
            } else {
                format!("{server}.{tool}")
            };
            Some((
                id,
                name,
                item.get("arguments").cloned().unwrap_or(Value::Null),
            ))
        }
        "fileChange" => Some((
            id,
            "file_change".into(),
            json!({ "changes": item.get("changes").cloned().unwrap_or(Value::Null) }),
        )),
        _ => None,
    }
}

fn write_json(stdin: &Mutex<Option<ChildStdin>>, value: &Value) -> Result<(), String> {
    use std::io::Write;
    let mut guard = stdin.lock().map_err(|e| format!("stdin lock: {e}"))?;
    let handle = guard.as_mut().ok_or("codex is not running")?;
    handle
        .write_all(json_line(value).as_bytes())
        .and_then(|_| handle.flush())
        .map_err(|e| format!("could not write to codex: {e}"))
}

struct CodexSession {
    cfg: SessionConfig,
    program: PathBuf,
    endpoint: McpEndpointInfo,
    child: Option<Child>,
    stdin: Arc<Mutex<Option<ChildStdin>>>,
    thread_id: Arc<Mutex<Option<String>>>,
    turn_id: Arc<Mutex<Option<String>>>,
    next_id: AtomicU64,
    turn_active: Arc<AtomicBool>,
    alive: Arc<AtomicBool>,
}

impl CodexSession {
    fn spawn(&mut self) -> Result<(), String> {
        let args = codex_args(&self.endpoint);
        let env = [(TOKEN_ENV.to_string(), self.endpoint.token.clone())];
        let cwd = self.cfg.scratch_dir.clone();
        std::fs::create_dir_all(&cwd).map_err(|e| format!("scratch dir: {e}"))?;
        let mut child = process::spawn_with_env(&self.program, &args, &cwd, &env)
            .map_err(|e| format!("could not start codex: {e}"))?;
        let stdin = child.stdin.take().ok_or("codex stdin unavailable")?;
        let stdout = child.stdout.take().ok_or("codex stdout unavailable")?;
        let stderr = child.stderr.take().ok_or("codex stderr unavailable")?;
        let tail: StderrTail = process::drain_stderr(stderr);
        *self.stdin.lock().map_err(|e| format!("stdin lock: {e}"))? = Some(stdin);
        self.alive = Arc::new(AtomicBool::new(true));

        let (ready_tx, ready_rx) = channel::<Result<(), String>>();
        let thread_start_id = self.next_id.fetch_add(1, Ordering::SeqCst);
        let reader = Reader {
            sink: self.cfg.sink.clone(),
            session_id: self.cfg.session_id.clone(),
            stdin: Arc::clone(&self.stdin),
            thread_id: Arc::clone(&self.thread_id),
            turn_id: Arc::clone(&self.turn_id),
            turn_active: Arc::clone(&self.turn_active),
            alive: Arc::clone(&self.alive),
            broker: Arc::clone(&self.cfg.broker),
            tools_on: self.cfg.options.native_tools,
            tail: tail.clone(),
            ready: Some(ready_tx),
            pending_thread_start: Some(thread_start_id),
        };
        std::thread::spawn(move || reader.run(stdout));

        write_json(
            &self.stdin,
            &json!({ "method": "initialize", "id": 0, "params": {
                "clientInfo": { "name": "renderly", "title": "Renderly", "version": env!("CARGO_PKG_VERSION") }
            }}),
        )?;
        write_json(
            &self.stdin,
            &json!({ "method": "initialized", "params": {} }),
        )?;
        let params = thread_start_params(&cwd, super::driver::system_prompt(), &self.cfg.options);
        write_json(
            &self.stdin,
            &json!({ "method": "thread/start", "id": thread_start_id, "params": params }),
        )?;

        let result = ready_rx
            .recv_timeout(READY_TIMEOUT)
            .unwrap_or_else(|_| Err("codex did not finish starting in time".into()));
        if let Err(message) = result {
            self.alive.store(false, Ordering::SeqCst);
            process::kill_tree(&mut child);
            return Err(message);
        }
        self.child = Some(child);
        (self.cfg.sink)(AgentEnvelope {
            session_id: self.cfg.session_id.clone(),
            event: AgentEvent::SessionStarted {
                agent_id: AgentId::Codex.program_name().into(),
            },
        });
        Ok(())
    }

    fn kill_process(&mut self) {
        self.alive.store(false, Ordering::SeqCst);
        if let Ok(mut guard) = self.stdin.lock() {
            *guard = None;
        }
        if let Some(mut child) = self.child.take() {
            process::kill_tree(&mut child);
        }
    }
}

impl AgentSession for CodexSession {
    fn send_turn(&mut self, text: &str) -> Result<(), String> {
        let thread = self
            .thread_id
            .lock()
            .map_err(|e| format!("thread lock: {e}"))?
            .clone()
            .ok_or("codex has no thread yet")?;
        if let Ok(mut t) = self.turn_id.lock() {
            *t = None;
        }
        let id = self.next_id.fetch_add(1, Ordering::SeqCst);
        self.turn_active.store(true, Ordering::SeqCst);
        let sent = write_json(
            &self.stdin,
            &json!({ "method": "turn/start", "id": id, "params": turn_start_params(&thread, text, &self.cfg.options) }),
        );
        if sent.is_err() {
            self.turn_active.store(false, Ordering::SeqCst);
        }
        sent
    }

    fn cancel_turn(&mut self) -> Result<(), String> {
        if !self.turn_active.load(Ordering::SeqCst) {
            return Ok(());
        }
        self.cfg.broker.cancel_all();
        let deadline = Instant::now() + INTERRUPT_WAIT;
        let turn = loop {
            if let Ok(t) = self.turn_id.lock() {
                if let Some(id) = t.clone() {
                    break Some(id);
                }
            }
            if Instant::now() >= deadline {
                break None;
            }
            std::thread::sleep(Duration::from_millis(20));
        };
        let thread = self.thread_id.lock().ok().and_then(|t| t.clone());
        match (thread, turn) {
            (Some(thread), Some(turn)) => {
                let id = self.next_id.fetch_add(1, Ordering::SeqCst);
                write_json(
                    &self.stdin,
                    &json!({ "method": "turn/interrupt", "id": id, "params": {
                        "threadId": thread, "turnId": turn,
                    }}),
                )
            }
            _ => {
                // No turn id to interrupt: stop the process. The next turn needs a new thread.
                self.kill_process();
                self.turn_active.store(false, Ordering::SeqCst);
                (self.cfg.sink)(AgentEnvelope {
                    session_id: self.cfg.session_id.clone(),
                    event: AgentEvent::TurnFinished {
                        stop_reason: "cancelled".into(),
                    },
                });
                Ok(())
            }
        }
    }

    fn shutdown(&mut self) {
        self.cfg.broker.cancel_all();
        self.kill_process();
        self.turn_active.store(false, Ordering::SeqCst);
    }
}

impl Drop for CodexSession {
    fn drop(&mut self) {
        self.shutdown();
    }
}

/// Fetch the model list from `codex app-server`: the handshake, then `model/list`. No thread and
/// no turn are started, so no model is called. Uses the user's own Codex config and login.
pub fn fetch_codex_models(program: &Path, scratch: &Path) -> AgentModels {
    if let Err(e) = std::fs::create_dir_all(scratch) {
        return AgentModels::failed(
            AgentId::Codex,
            ModelStatus::Error,
            format!("scratch dir: {e}"),
        );
    }
    let mut child = match process::spawn(program, &["app-server".to_string()], scratch) {
        Ok(c) => c,
        Err(e) => {
            return AgentModels::failed(
                AgentId::Codex,
                ModelStatus::Error,
                format!("could not start codex: {e}"),
            )
        }
    };
    let (Some(mut stdin), Some(stdout)) = (child.stdin.take(), child.stdout.take()) else {
        process::kill_tree(&mut child);
        return AgentModels::failed(
            AgentId::Codex,
            ModelStatus::Error,
            "codex pipes unavailable",
        );
    };
    use std::io::Write;
    let requests = [
        json!({ "method": "initialize", "id": 0, "params": {
            "clientInfo": { "name": "renderly", "title": "Renderly", "version": env!("CARGO_PKG_VERSION") }
        }}),
        json!({ "method": "initialized", "params": {} }),
        json!({ "method": "model/list", "id": 1, "params": { "includeHidden": false } }),
    ];
    for r in &requests {
        if stdin.write_all(json_line(r).as_bytes()).is_err() {
            break;
        }
    }
    let _ = stdin.flush();
    let reply = super::models::await_reply(stdout, MODEL_LIST_TIMEOUT, |v| {
        v.get("id").and_then(Value::as_u64) == Some(1)
    });
    process::kill_tree(&mut child);
    let Some(reply) = reply else {
        return AgentModels::failed(
            AgentId::Codex,
            ModelStatus::Error,
            "Codex did not answer the model request in time.",
        );
    };
    if let Some(err) = reply.get("error") {
        let message = err
            .get("message")
            .and_then(Value::as_str)
            .unwrap_or("model/list failed")
            .to_string();
        let lower = message.to_ascii_lowercase();
        let status = if lower.contains("login") || lower.contains("auth") || lower.contains("sign")
        {
            ModelStatus::NotSignedIn
        } else {
            ModelStatus::Error
        };
        let shown = if status == ModelStatus::NotSignedIn {
            "Codex is not signed in. Run `codex login` in a terminal, then refresh.".to_string()
        } else {
            message
        };
        return AgentModels::failed(AgentId::Codex, status, shown);
    }
    parse_codex_models(reply.get("result").unwrap_or(&Value::Null))
        .unwrap_or_else(|e| AgentModels::failed(AgentId::Codex, ModelStatus::Error, e))
}

/// Reads server output on its own thread: answers the handshake, routes notifications to
/// events, and turns approval requests into broker decisions.
struct Reader {
    sink: EventSink,
    session_id: String,
    stdin: Arc<Mutex<Option<ChildStdin>>>,
    thread_id: Arc<Mutex<Option<String>>>,
    turn_id: Arc<Mutex<Option<String>>>,
    turn_active: Arc<AtomicBool>,
    alive: Arc<AtomicBool>,
    broker: Arc<super::permission::PermissionBroker>,
    tools_on: bool,
    tail: StderrTail,
    ready: Option<Sender<Result<(), String>>>,
    pending_thread_start: Option<u64>,
}

impl Reader {
    fn emit(&self, event: AgentEvent) {
        (self.sink)(AgentEnvelope {
            session_id: self.session_id.clone(),
            event,
        });
    }

    fn run(mut self, stdout: impl std::io::Read) {
        process::read_lines(stdout, |line| self.handle(line));
        // EOF: report only if this process was not deliberately stopped.
        if self.alive.swap(false, Ordering::SeqCst) {
            if let Some(ready) = self.ready.take() {
                let _ = ready.send(Err(format!(
                    "codex exited while starting:\n{}",
                    self.tail.last_lines()
                )));
            } else {
                if self.turn_active.swap(false, Ordering::SeqCst) {
                    self.emit(AgentEvent::TurnFinished {
                        stop_reason: "error".into(),
                    });
                }
                self.broker.cancel_all();
                self.emit(AgentEvent::Error {
                    message: format!("Codex exited unexpectedly:\n{}", self.tail.last_lines()),
                });
            }
        }
    }

    fn handle(&mut self, line: &str) {
        match classify(line) {
            Incoming::Response { id, result, error } => {
                if let Some(err) = error {
                    let message = err
                        .get("message")
                        .and_then(Value::as_str)
                        .unwrap_or("request failed")
                        .to_string();
                    if self.pending_thread_start == Some(id) {
                        if let Some(ready) = self.ready.take() {
                            let _ = ready.send(Err(message));
                        }
                    } else {
                        self.emit(AgentEvent::Error { message });
                    }
                    return;
                }
                if self.pending_thread_start == Some(id) {
                    match result
                        .get("thread")
                        .and_then(|t| t.get("id"))
                        .and_then(Value::as_str)
                    {
                        Some(thread) => {
                            if let Ok(mut t) = self.thread_id.lock() {
                                *t = Some(thread.to_string());
                            }
                            if let Some(ready) = self.ready.take() {
                                let _ = ready.send(Ok(()));
                            }
                        }
                        None => {
                            if let Some(ready) = self.ready.take() {
                                let _ = ready.send(Err("codex returned no thread".into()));
                            }
                        }
                    }
                    return;
                }
                if let Some(turn) = result
                    .get("turn")
                    .and_then(|t| t.get("id"))
                    .and_then(Value::as_str)
                {
                    if let Ok(mut t) = self.turn_id.lock() {
                        *t = Some(turn.to_string());
                    }
                }
            }
            Incoming::Request { id, method, params } => match method.as_str() {
                "item/commandExecution/requestApproval" | "item/fileChange/requestApproval" => {
                    if self.tools_on {
                        self.spawn_approval(id, method, params);
                    } else {
                        // The agent's own tools are off: decline without asking.
                        let _ = write_json(
                            &self.stdin,
                            &json!({ "id": id, "result": { "decision": "decline" } }),
                        );
                    }
                }
                "mcpServer/elicitation/request" => {
                    let server = params
                        .get("serverName")
                        .and_then(Value::as_str)
                        .unwrap_or("");
                    let action = if server == "renderly" {
                        "accept"
                    } else {
                        "decline"
                    };
                    let _ = write_json(
                        &self.stdin,
                        &json!({ "id": id, "result": { "action": action } }),
                    );
                }
                other => {
                    let reply = json!({ "id": id, "error": {
                        "code": -32601,
                        "message": format!("Renderly does not handle {other}"),
                    }});
                    let _ = write_json(&self.stdin, &reply);
                }
            },
            Incoming::Notification { method, params } => {
                if method == "turn/completed" {
                    self.turn_active.store(false, Ordering::SeqCst);
                }
                for event in notification_events(&method, &params) {
                    self.emit(event);
                }
            }
            Incoming::Unknown => {}
        }
    }

    /// Ask the broker on a helper thread (the reader keeps reading), then answer the server.
    fn spawn_approval(&self, id: Value, method: String, params: Value) {
        let broker = Arc::clone(&self.broker);
        let stdin = Arc::clone(&self.stdin);
        std::thread::spawn(move || {
            let tool = format!("codex:{method}");
            let decision = tauri::async_runtime::block_on(broker.decide(&tool, &params));
            let decision_value = match decision {
                super::permission::Decision::Allow => "accept",
                super::permission::Decision::Deny { .. } => "decline",
            };
            let _ = write_json(
                &stdin,
                &json!({ "id": id, "result": { "decision": decision_value } }),
            );
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn endpoint() -> McpEndpointInfo {
        McpEndpointInfo {
            url: "http://127.0.0.1:50123/mcp".into(),
            token: "secret-token-value".into(),
        }
    }

    #[test]
    fn argv_carries_the_server_url_and_the_token_env_name_only() {
        let args = codex_args(&endpoint());
        assert_eq!(
            args,
            vec![
                "-c",
                "mcp_servers.renderly.url=\"http://127.0.0.1:50123/mcp\"",
                "-c",
                "mcp_servers.renderly.bearer_token_env_var=\"RENDERLY_AGENT_TOKEN\"",
                "-c",
                "mcp_servers.renderly.default_tools_approval_mode=\"approve\"",
                "-c",
                "project_doc_max_bytes=0",
                "app-server",
            ]
        );
        // The secret is never in argv.
        assert!(!args.iter().any(|a| a.contains("secret-token-value")));
    }

    #[test]
    fn the_token_env_name_is_the_one_the_override_names() {
        assert_eq!(TOKEN_ENV, "RENDERLY_AGENT_TOKEN");
        assert!(codex_args(&endpoint())
            .iter()
            .any(|a| a.contains(&format!("\"{TOKEN_ENV}\""))));
    }

    #[test]
    fn thread_start_replaces_the_instructions_and_sets_read_only_by_default() {
        let p = thread_start_params(Path::new("C:/scratch"), "BRIEF", &LaunchOptions::default());
        assert_eq!(p["baseInstructions"], "BRIEF");
        assert_eq!(p["sandbox"], "read-only");
        assert_eq!(p["approvalPolicy"], "on-request");
        assert!(p.get("model").is_none(), "no model chosen, none sent");
        assert!(p.get("developerInstructions").is_none());
    }

    #[test]
    fn tools_switch_sets_workspace_write_and_asks_instead_of_declining() {
        let options = LaunchOptions {
            native_tools: true,
            model: Some("gpt-6-terra".into()),
            ..LaunchOptions::default()
        };
        let p = thread_start_params(Path::new("C:/scratch"), "BRIEF", &options);
        assert_eq!(p["sandbox"], "workspace-write");
        assert_eq!(p["model"], "gpt-6-terra");
        assert_eq!(sandbox_for(&options), ("workspace-write", true));
        assert_eq!(sandbox_for(&LaunchOptions::default()), ("read-only", false));
    }

    #[test]
    fn turn_start_sends_effort_only_when_chosen() {
        let none = turn_start_params("thr_1", "hi", &LaunchOptions::default());
        assert!(none.get("effort").is_none());
        let some = turn_start_params(
            "thr_1",
            "hi",
            &LaunchOptions {
                effort: Some("medium".into()),
                ..LaunchOptions::default()
            },
        );
        assert_eq!(some["effort"], "medium");
        assert_eq!(some["input"][0]["text"], "hi");
    }

    #[test]
    fn classifies_responses_requests_and_notifications() {
        assert!(matches!(
            classify(r#"{"id":1,"result":{"thread":{"id":"thr_1"}}}"#),
            Incoming::Response { id: 1, .. }
        ));
        assert!(matches!(
            classify(r#"{"id":900,"method":"item/commandExecution/requestApproval","params":{}}"#),
            Incoming::Request { .. }
        ));
        assert!(matches!(
            classify(r#"{"method":"turn/completed","params":{}}"#),
            Incoming::Notification { .. }
        ));
        assert_eq!(classify("garbage"), Incoming::Unknown);
    }

    #[test]
    fn agent_message_deltas_become_text() {
        let evs = notification_events(
            "item/agentMessage/delta",
            &json!({ "delta": "Hi", "itemId": "i1" }),
        );
        assert_eq!(evs, vec![AgentEvent::TextDelta { text: "Hi".into() }]);
    }

    #[test]
    fn command_items_become_tool_cards() {
        let started = notification_events(
            "item/started",
            &json!({ "item": { "id": "c1", "type": "commandExecution", "command": "ls" } }),
        );
        assert!(
            matches!(&started[0], AgentEvent::ToolStarted { id, name, .. } if id == "c1" && name == "shell")
        );
        let done = notification_events(
            "item/completed",
            &json!({ "item": { "id": "c1", "type": "commandExecution", "status": "failed", "aggregatedOutput": "boom" } }),
        );
        assert_eq!(
            done,
            vec![AgentEvent::ToolFinished {
                id: "c1".into(),
                output_summary: "boom".into(),
                is_error: true
            }]
        );
    }

    #[test]
    fn messages_and_reasoning_items_are_not_tool_cards() {
        assert!(notification_events(
            "item/started",
            &json!({ "item": { "id": "m1", "type": "agentMessage" } })
        )
        .is_empty());
    }

    #[test]
    fn turn_completed_reports_its_status() {
        assert_eq!(
            notification_events(
                "turn/completed",
                &json!({ "turn": { "status": "interrupted" } })
            ),
            vec![AgentEvent::TurnFinished {
                stop_reason: "interrupted".into()
            }]
        );
    }

    #[test]
    fn unknown_notifications_are_ignored() {
        assert!(notification_events("thread/started", &json!({})).is_empty());
    }

    #[test]
    fn renderly_mcp_calls_are_named_like_claude_code_names_them() {
        let started = notification_events(
            "item/started",
            &json!({ "item": { "id": "t1", "type": "mcpToolCall", "server": "renderly", "tool": "edit", "arguments": {"commands": []} } }),
        );
        assert!(
            matches!(&started[0], AgentEvent::ToolStarted { name, .. } if name == "mcp__renderly__edit")
        );
        let done = notification_events(
            "item/completed",
            &json!({ "item": { "id": "t1", "type": "mcpToolCall", "server": "renderly", "tool": "edit",
                "status": "completed", "result": { "content": [{ "type": "text", "text": "Applied 1 command(s)" }] } } }),
        );
        assert_eq!(
            done,
            vec![AgentEvent::ToolFinished {
                id: "t1".into(),
                output_summary: "Applied 1 command(s)".into(),
                is_error: false
            }]
        );
    }
}
